#import <Foundation/Foundation.h>
#import "../Sources/AMOperation.h"
static NSUInteger assertions;
static void Check(BOOL value,NSString *message){@synchronized(NSProcessInfo.processInfo){assertions++;}if(!value){fprintf(stderr,"FAIL: %s\n",message.UTF8String);exit(1);}}
static void Wait(dispatch_semaphore_t semaphore){Check(dispatch_semaphore_wait(semaphore,dispatch_time(DISPATCH_TIME_NOW,5*NSEC_PER_SEC))==0,@"scheduled work completes without deadlock");}
int main(void){@autoreleasepool{
    dispatch_semaphore_t started=dispatch_semaphore_create(0),release=dispatch_semaphore_create(0),finished=dispatch_semaphore_create(0);
    NSMutableArray *order=NSMutableArray.array;NSObject *lock=NSObject.new;
    NSString *first=AMOperationEnqueue(@"first",@"test",@"fixture",@[@"repo"],0,^(NSString *key){dispatch_semaphore_signal(started);dispatch_semaphore_wait(release,DISPATCH_TIME_FOREVER);AMOperationFinish(key,@"success",@"");},nil);Wait(started);
    NSString *duplicate=AMOperationEnqueue(@"first",@"test",@"fixture",@[@"repo"],0,^(NSString *key){Check(NO,@"duplicate never executes");},nil);Check([first isEqual:duplicate],@"active identical requests coalesce");
    for(NSString *name in @[@"auto",@"manual"]){AMOperationEnqueue(name,@"test",name,@[@"repo"],[name isEqual:@"manual"] ? 100:0,^(NSString *key){@synchronized(lock){[order addObject:name];}AMOperationFinish(key,@"success",@"");dispatch_semaphore_signal(finished);},nil);}
    __block BOOL cancelledBefore=NO;NSString *cancelled=AMOperationEnqueue(@"cancel",@"test",@"fixture",@[@"repo"],200,^(NSString *key){Check(NO,@"cancelled queued request must never execute");},^(BOOL before){cancelledBefore=before;});AMOperationCancel(cancelled);Check(cancelledBefore,@"queued cancellation reports no execution");Check(AMQueuedOperationCount()==2,@"only pending requests count as queued");
    AMOperationEnqueue(@"browse",@"test",@"other",@[@"independent"],0,^(NSString *key){AMOperationFinish(key,@"success",@"");dispatch_semaphore_signal(finished);},nil);Wait(finished);Check(order.count==0,@"independent resource runs while repository is occupied");
    dispatch_semaphore_signal(release);Wait(finished);Wait(finished);Check([order isEqual:@[@"manual",@"auto"]],@"manual request runs before pending automatic work");
    dispatch_semaphore_t modelStarted=dispatch_semaphore_create(0),modelRelease=dispatch_semaphore_create(0),modelDone=dispatch_semaphore_create(0);__block NSUInteger calls=0;
    for(NSUInteger i=0;i<2;i++)dispatch_async(dispatch_get_global_queue(QOS_CLASS_DEFAULT,0),^{NSError *error=nil;id value=AMPerformModelOperation(@"shared-model",@"fixture",YES,nil,^id(NSError **problem){@synchronized(lock){calls++;}dispatch_semaphore_signal(modelStarted);dispatch_semaphore_wait(modelRelease,DISPATCH_TIME_FOREVER);return @"result";},&error);Check([value isEqual:@"result"] && !error,@"all duplicate callers receive the same result");dispatch_semaphore_signal(modelDone);});
    Wait(modelStarted);NSDate *deadline=[NSDate dateWithTimeIntervalSinceNow:5];BOOL joined=NO;while(!joined && deadline.timeIntervalSinceNow>0){for(NSDictionary *row in AMOperations())if([row[@"requests"] integerValue]==2)joined=YES;if(!joined)[NSThread sleepForTimeInterval:.001];}Check(joined,@"both model callers joined before completing transport");dispatch_semaphore_signal(modelRelease);Wait(modelDone);Wait(modelDone);Check(calls==1,@"duplicate model requests invoke transport once");
    dispatch_semaphore_t occupied=dispatch_semaphore_create(0),unblock=dispatch_semaphore_create(0),cancelDone=dispatch_semaphore_create(0);
    AMOperationEnqueue(@"occupy-model",@"fixture",@"occupy",@[@"model-service"],0,^(NSString *identifier){dispatch_semaphore_signal(occupied);dispatch_semaphore_wait(unblock,DISPATCH_TIME_FOREVER);AMOperationFinish(identifier,@"success",@"");},nil);Wait(occupied);
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_DEFAULT,0),^{NSError *error=nil;id value=AMPerformModelOperation(@"cancel-before-send",@"cancel-target",YES,nil,^id(NSError **problem){Check(NO,@"cancelled model transport must not run");return nil;},&error);Check(!value && error.code==NSUserCancelledError,@"queued model cancellation unblocks all waiting callers");dispatch_semaphore_signal(cancelDone);});
    deadline=[NSDate dateWithTimeIntervalSinceNow:5];NSString *queuedID=nil;while(!queuedID && deadline.timeIntervalSinceNow>0){for(NSDictionary *row in AMOperations())if([row[@"target"] isEqual:@"cancel-target"] && [row[@"state"] isEqual:@"queued"])queuedID=row[@"id"];if(!queuedID)[NSThread sleepForTimeInterval:.001];}Check(queuedID!=nil,@"model request visibly waits for the occupied model lane");AMOperationCancel(queuedID);Wait(cancelDone);dispatch_semaphore_signal(unblock);
    dispatch_semaphore_t batchStarted=dispatch_semaphore_create(0),batchRelease=dispatch_semaphore_create(0);__block NSUInteger cancelledCount=0;
    AMOperationEnqueue(@"batch-owner",@"fixture",@"fixture",@[@"batch-test"],0,^(NSString *identifier){dispatch_semaphore_signal(batchStarted);dispatch_semaphore_wait(batchRelease,DISPATCH_TIME_FOREVER);AMOperationFinish(identifier,@"success",@"");},nil);Wait(batchStarted);
    for(NSUInteger i=0;i<3;i++)AMOperationEnqueue([NSString stringWithFormat:@"batch-%lu",(unsigned long)i],@"fixture",@"fixture",@[@"batch-test"],0,^(NSString *identifier){Check(NO,@"cancelling a batch never launches another pending request");},^(BOOL before){if(before)cancelledCount++;});
    AMCancelQueuedOperations();Check(cancelledCount==3 && AMQueuedOperationCount()==0,@"all queued requests cancel atomically before the scheduler resumes");dispatch_semaphore_signal(batchRelease);
    dispatch_semaphore_t writing=dispatch_semaphore_create(0),writeEnd=dispatch_semaphore_create(0);__block NSUInteger writeCancellations=0;
    NSString *writeID=AMOperationSchedule(@"protected-write",@"fixture",@"fixture",@[@"write-policy"],0,NO,^(NSString *identifier){dispatch_semaphore_signal(writing);dispatch_semaphore_wait(writeEnd,DISPATCH_TIME_FOREVER);AMOperationFinish(identifier,@"success",@"");},^(BOOL before){writeCancellations++;});Wait(writing);AMOperationCancel(writeID);Check(writeCancellations==0,@"running Git writes cannot be interrupted even when a queued-cancel hook exists");
    NSString *waitingWrite=AMOperationSchedule(@"waiting-write",@"fixture",@"fixture",@[@"write-policy"],0,NO,^(NSString *identifier){Check(NO,@"cancelled pending write never executes");},^(BOOL before){if(before)writeCancellations++;});AMOperationCancel(waitingWrite);Check(writeCancellations==1,@"queued write cancellation still notifies its owner");dispatch_semaphore_signal(writeEnd);
    printf("PASS: %lu scheduler assertions\n",(unsigned long)assertions);
}return 0;}
